// === MixLLM 4 级 Software Pipeline 的伪代码 ===
// 流水线阶段:
//   L1: Global → Shared Memory (async copy, cp.async)
//   L2: Shared → Register load
//   L3: SIMT Dequant (vsub4 + I2F prep)
//   L4: Tensor Core MMA (int8 mma.sync)

// 两个输出 buffer
float32 per_group_accum[M_tile, N_tile] = {0}   // per-group partial
float32 global_accum[M_tile, N_tile] = {0}      // global result

for g = 0 to K/128:  // 遍历所有 quantization groups
    // ===== L1: 预取下一 group =====
    // 异步拷贝下一 group 的 weight tile + scale + zero 到 shared memory
    cp_async(&smem_weight[next_group], &gmem_weight[next_group])
    cp_async(&smem_scale[next_group], &gmem_scale[next_group])

    // ===== L2: 加载当前 group activation =====
    // 从 shared memory 读取当前 group 的 activation tile
    A_reg = smem_activation[current_group]

    // ===== L3: SIMT Dequant（与 L4 Tensor Core 并行）=====
    // 在 CUDA core 上执行 dequant（vsub4 zero-point 减法）
    // 这可以和下一个 tile 的 MMA 在 Tensor Core 上并行
    W_deq_int8 = vsub4(smem_weight[current_group], smem_zero[current_group])

    // ===== L4: Tensor Core MMA =====
    // int8 MMA: A_q[int8] × W_deq[int8] → accumulator[int32]
    // bias 已融合进 accumulator 初始值（Fast I2F trick）
    mma_sync(&per_group_accum, A_reg, W_deq_int8)

    // ===== L4→L1 过渡: per-group reduction =====
    // 每组结束后: Fast I2F + scale multiply → 累加到 global
    for (m, n) in per_group_accum:
        // I2F via bias trick（accumulator 已含 bias）
        val = uint_as_float(per_group_accum[m,n]) - bias_float
        val *= scale_w[g] * scale_a[g]
        global_accum[m,n] += val
    per_group_accum = {0}  // 清零为下一 group（同时重新初始化 bias）

// ===== 最终 Epilogue =====
// 与其他精度分区的 output scatter 合并
C_fp16[m,n] = fp16(global_accum[m,n])
```

**量化组 tile 的作用**：group=128 意味着每 128 个 K 维度元素后需要切换 scale/zero——这成为流水线的自然"flush"边界。MixLLM 的 pipeline 利用这个周期性中断执行 per-group reduction（Fast I2F + scale multiply），避免了跨 group 的累加溢出（int32 accumulator 不能跨 group 直接累加，因为不同 group 的 scale 不同）。

